using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
public sealed class CodexSessionTitles {
 readonly Dictionary<string,string> titles=new Dictionary<string,string>();DateTime next;string loadedHome;
 public static string Clean(object value){var text=value as string;if(String.IsNullOrWhiteSpace(text))return "";text=new string(text.Where(c=>!Char.IsControl(c)).ToArray()).Trim();return text.Length>120?text.Substring(0,120)+"…":text;}
 public string Resolve(string id,object supplied,string home){string explicitTitle=Clean(supplied);if(explicitTitle.Length>0)return explicitTitle;if(String.IsNullOrWhiteSpace(home))home=Environment.GetEnvironmentVariable("CODEX_HOME");if(String.IsNullOrWhiteSpace(home))home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".codex");if(loadedHome!=home||DateTime.UtcNow>=next){loadedHome=home;next=DateTime.UtcNow.AddSeconds(10);titles.Clear();try{string path=Path.Combine(home,"session_index.jsonl");if(File.Exists(path)&&new FileInfo(path).Length<=8388608&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)==0){var json=new JavaScriptSerializer();foreach(string line in File.ReadLines(path)){if(line.Length>16384)continue;try{var item=json.Deserialize<Dictionary<string,object>>(line);object key,name;if(item!=null&&item.TryGetValue("id",out key)&&item.TryGetValue("thread_name",out name)&&key is string){string title=Clean(name);if(title.Length>0)titles[(string)key]=title;}}catch(ArgumentException){}catch(InvalidOperationException){}}}}catch(IOException){}catch(UnauthorizedAccessException){}catch(ArgumentException){}}string result;return titles.TryGetValue(id,out result)?result:"";}
}
